<span class="line">    <span class="token annotation punctuation">@SystemMessage</span><span class="token punctuation">(</span>fromResource<span class="token operator">=</span><span class="token string">&quot;zhaozhi-prompt-template.txt&quot;</span><span class="token punctuation">)</span></span>
